A practical Perl approach is to parse each row, extract the ID from the first column, and sort by that ID:

```perl
use strict;
use warnings;
use Text::CSV_XS;

my $csv = Text::CSV_XS->new({ binary => 1, empty_is_undef => 1 })
    or die Text::CSV_XS->error_diag();

my @rows;

while (my $line = <STDIN>) {
    chomp $line;
    next if $line =~ /^\s*$/;

    $csv->parse($line) or die "CSV parse error: " . $csv->error_diag();
    my @cols = $csv->fields();

    push @rows, \@cols;
}

@rows = sort {
    my ($a_id) = defined $a->[0] ? ($a->[0] =~ /(XYZ-ZTE-\d+)/) : ('');
    my ($b_id) = defined $b->[0] ? ($b->[0] =~ /(XYZ-ZTE-\d+)/) : ('');
    $a_id cmp $b_id;
} @rows;

for my $row (@rows) {
    print join(",", map { defined($_) ? $_ : "" } @$row), "\n";
}
```

