`su` reads the password from the controlling terminal, so you generally can’t safely pipe or pass it in directly from the shell. To keep it hidden, use a terminal automation tool like `expect`, which can spawn `su`, detect the `Password:` prompt, send the password, and suppress logging so it doesn’t appear on screen or in output.

Example:

```tcl
stty echo
log_user 0
set timeout 2

if [catch "spawn su root" reason] {
    send_user "Failed to spawn su: $reason\n"
    exit 1
}

expect "Password:"
send "$PASSWORD\r"
expect "\r\n"

log_user 1
expect {
    "# " { send_user "\nsu successful.\n" }
    timeout { send_user "\nsu timed out.\n"; exit 1 }
    "incorrect" { send_user "\nsu failed.\n"; exit 1 }
}
```

